"""Live ledger status of settled claims: is the claim's receipt in the ledger?"""
from hbexpense.models import POSTED
from hbexpense.util.dates import month_bounds, month_of

BOOKED = "booked"
NOT_BOOKED = "not_booked"


class LedgerStatusService:
    def __init__(self, ledger):
        self.ledger = ledger

    def statuses(self, claims):
        """Map claim id -> "booked" / "not_booked" / None (not settled yet).

        Reads the ledger on every call (no cache) so the screen always shows
        the current state. Uses `list` per month, not `show` per receipt,
        because per-entry lookups are billed and kept off (EXP-412).
        """
        result = {c.claim_id: None for c in claims}
        receipts_by_month = {}
        for claim in claims:
            if claim.status != POSTED or not claim.receipt:
                continue
            month = month_of(claim.spent_on)
            if month not in receipts_by_month:
                date_from, date_to = month_bounds(month)
                rows = self.ledger.list_rows(date_from, date_to)
                receipts_by_month[month] = {row.receipt for row in rows}
            booked = claim.receipt in receipts_by_month[month]
            result[claim.claim_id] = BOOKED if booked else NOT_BOOKED
        return result

